<?php session_start(); $dbPath='/var/data/visitador.sqlite'; if(!is_dir('/var/data')) $dbPath=__DIR__.'/data/visitador.sqlite'; $pdoAuth=new PDO('sqlite:'.$dbPath); $pdoAuth->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION); $pdoAuth->exec("CREATE TABLE IF NOT EXISTS usuarios (id_usuario INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL UNIQUE,contrasena TEXT NOT NULL)"); if(!$pdoAuth->query("SELECT COUNT(*) FROM usuarios")->fetchColumn()){$st=$pdoAuth->prepare('INSERT INTO usuarios(nombre,contrasena) VALUES(?,?)');$st->execute(['Demo',password_hash('Heather323',PASSWORD_DEFAULT)]);} function require_login(){if(empty($_SESSION['usuario'])){header('Location: login.php');exit;}} function usuario_actual(){global $pdoAuth;$st=$pdoAuth->prepare('SELECT id_usuario,nombre FROM usuarios WHERE id_usuario=?');$st->execute([$_SESSION['usuario']??0]);return $st->fetch(PDO::FETCH_ASSOC);}
